INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('7714b7c6-9283-4ab8-802e-cbcfba5ddc96','6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f',$$Brock initiated a homelessness emergency declaration and served on the US Conference of Mayors Homelessness Task Force, describing an approach that balances law enforcement with compassionate solutions.$$,ARRAY['https://patch.com/california/santamonica/candidate-profile-phil-brock-santa-monica-city-council']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
