INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('7714b7c6-9283-4ab8-802e-cbcfba5ddc96','fb25c1ac-91cc-49bf-8afc-c7fa22ef45e4',$$Brock supports slow growth and reduced traffic, expressing concern that big developers and the State want to replace the heart of the city with tall, dense buildings.$$,ARRAY['https://www.votebrock.org/issues/a-statement-of-purpose']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
